import { useState, useEffect } from 'react'
import {
  getMerchantUserList,
  PlatformUserTypes
} from '@/apis/admin/platform-user'
import { Card, Row, Col, Select, InputNumber, Button } from 'antd'
import { PlusOutlined, DeleteOutlined, ShopOutlined } from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'

interface MerchantConfigFormProps {
  /** 商户配置列表 */
  merchants: PlatformUserTypes.MerchantProfitInfoDto[]
  /** 配置变化回调 */
  onChange: (merchants: PlatformUserTypes.MerchantProfitInfoDto[]) => void
  /** 是否显示标题 */
  showTitle?: boolean
  /** 卡片背景色 */
  cardBackground?: string
}

/**
 * 商户分润配置表单组件
 * 用于配置商户绑定和分成比例
 */
const MerchantConfigForm: React.FC<MerchantConfigFormProps> = ({
  merchants,
  onChange,
  showTitle = true,
  cardBackground = '#F8FAFC'
}) => {
  const [merchantList, setMerchantList] = useState<PlatformUserTypes.MerchantUserListDto[]>([])

  // 加载商户列表
  useEffect(() => {
    const loadMerchantList = async () => {
      try {
        const res = await getMerchantUserList({ status: 1, pageSize: 50 })
        if (res.code === ResultEnum.SUCCESS && res.data?.list) {
          setMerchantList(res.data.list)
        }
      } catch (e) {
        console.error('加载商户列表失败:', e)
      }
    }
    loadMerchantList()
  }, [])

  // 计算公司分成
  const calcCompanyRate = () => {
    const total = merchants.reduce((sum, m) => sum + (m.divideRatio || 0), 0)
    return 100 - total
  }

  // 添加商户行
  const addMerchantRow = () => {
    const newRow: PlatformUserTypes.MerchantProfitInfoDto = {
      merchantId: 0,
      merchantName: '',
      divideRatio: 0
    }
    onChange([...merchants, newRow])
  }

  // 移除商户行
  const removeMerchantRow = (index: number) => {
    if (merchants.length <= 1) {
      return
    }
    const newList = merchants.filter((_, i) => i !== index)
    onChange(newList)
  }

  // 更新商户配置
  const updateMerchant = (
    index: number,
    field: keyof PlatformUserTypes.MerchantProfitInfoDto,
    value: any
  ) => {
    const newList = [...merchants]
    newList[index] = { ...newList[index], [field]: value }
    onChange(newList)
  }

  const companyRate = calcCompanyRate()

  return (
    <Card size="small" style={{ background: cardBackground }}>
      {showTitle && (
        <div style={{ fontWeight: 600, marginBottom: 12 }}>
          <ShopOutlined style={{ color: '#2563EB', marginRight: 6 }} />
          商户绑定配置
        </div>
      )}

      {merchants.map((item, index) => (
        <Card
          key={index}
          size="small"
          style={{ marginBottom: 12, background: '#fff' }}
          bodyStyle={{ padding: 12 }}
        >
          <Row gutter={16} align="middle">
            <Col flex="auto">
              <Select
                placeholder="选择商户"
                value={item.merchantId || undefined}
                onChange={value => {
                  const merchant = merchantList.find(m => m.id === value)
                  updateMerchant(index, 'merchantId', value)
                  if (merchant) {
                    updateMerchant(index, 'merchantName', merchant.merchantName)
                  }
                }}
                style={{ width: '100%' }}
              >
                {merchantList.map(m => (
                  <Select.Option key={m.id} value={m.id}>
                    {m.merchantName}
                  </Select.Option>
                ))}
              </Select>
            </Col>
            <Col style={{ width: 120 }}>
              <InputNumber
                min={0}
                max={100}
                value={item.divideRatio}
                onChange={value => updateMerchant(index, 'divideRatio', value)}
                addonAfter="%"
                style={{ width: '100%' }}
              />
            </Col>
            {merchants.length > 1 && (
              <Col>
                <Button
                  type="text"
                  danger
                  icon={<DeleteOutlined />}
                  onClick={() => removeMerchantRow(index)}
                />
              </Col>
            )}
          </Row>
        </Card>
      ))}

      <Button type="dashed" block icon={<PlusOutlined />} onClick={addMerchantRow}>
        添加商户
      </Button>

      <Card
        size="small"
        style={{
          marginTop: 16,
          background: companyRate >= 0 ? '#EFF6FF' : '#FEF2F2',
          borderColor: companyRate >= 0 ? '#BFDBFE' : '#FECACA'
        }}
      >
        <div style={{ fontSize: 13, color: companyRate >= 0 ? '#64748B' : '#DC2626' }}>
          公司分成 = 100% - 商户分成合计
        </div>
        <div style={{ fontSize: 16, fontWeight: 600, marginTop: 4 }}>
          公司分成：
          <span style={{ color: companyRate >= 0 ? '#2563EB' : '#DC2626' }}>
            {companyRate}%
          </span>
        </div>
      </Card>
    </Card>
  )
}

export default MerchantConfigForm
