import { useState, useEffect } from 'react'
import { DeviceManagementTypes } from '@/apis/admin/device-management'
import {
  editDeviceMerchantProfit,
  PlatformUserTypes
} from '@/apis/admin/platform-user'
import DeviceSelector from '@/components/DeviceSelector'
import MerchantConfigForm from '../MerchantConfigForm'
import { Modal, Form, Space, message } from 'antd'
import { ResultEnum } from '@/utils/enums/httpEnum'

interface BatchProfitConfigModalProps {
  open: boolean
  onCancel: () => void
  onSuccess: () => void
}

const BatchProfitConfigModal: React.FC<BatchProfitConfigModalProps> = ({
  open,
  onCancel,
  onSuccess
}) => {
  const [form] = Form.useForm()
  const [confirmLoading, setConfirmLoading] = useState(false)
  const [selectedDevices, setSelectedDevices] = useState<DeviceManagementTypes.DeviceListDto[]>([])
  const [batchMerchants, setBatchMerchants] = useState<PlatformUserTypes.MerchantProfitInfoDto[]>([
    { merchantId: 0, merchantName: '', divideRatio: 0 }
  ])

  // 弹窗打开时重置数据
  useEffect(() => {
    if (open) {
      form.resetFields()
      setSelectedDevices([])
      setBatchMerchants([{ merchantId: 0, merchantName: '', divideRatio: 0 }])
    }
  }, [open, form])

  // 提交批量配置
  const handleSave = async () => {
    try {
      await form.validateFields()
      if (selectedDevices.length === 0) {
        message.error('请至少选择一个柜子')
        return
      }

      // 过滤掉未选择商户的配置
      const validMerchants = batchMerchants.filter(m => m.merchantId > 0)
      if (validMerchants.length === 0) {
        message.error('请至少选择一个商户')
        return
      }

      // 计算公司分成
      const total = validMerchants.reduce((sum, m) => sum + (m.divideRatio || 0), 0)
      const companyRate = 100 - total
      if (companyRate < 0) {
        message.error('商户分成合计不能超过 100%')
        return
      }

      setConfirmLoading(true)

      // 批量配置：为每个选中的设备调用接口
      const merchant = validMerchants[0]
      const results = await Promise.all(
        selectedDevices.map(device =>
          editDeviceMerchantProfit(device.id, {
            deviceId: device.id,
            merchantId: merchant.merchantId,
            merchantName: merchant.merchantName,
            divideRatio: merchant.divideRatio
          })
        )
      )

      const successCount = results.filter(r => r.code === ResultEnum.SUCCESS).length
      const failCount = results.length - successCount

      if (failCount === 0) {
        message.success(`已为 ${successCount} 个柜子配置分润`)
        onSuccess()
      } else {
        message.warning(`配置完成：成功 ${successCount} 个，失败 ${failCount} 个`)
        if (successCount > 0) {
          onSuccess()
        }
      }
    } catch (e) {
      console.error(e)
      message.error('配置失败')
    } finally {
      setConfirmLoading(false)
    }
  }

  return (
    <Modal
      title="批量配置分润"
      open={open}
      onCancel={onCancel}
      onOk={handleSave}
      confirmLoading={confirmLoading}
      width={720}
    >
      <Form form={form} layout="vertical">
        {/* 柜子选择 */}
        <Form.Item
          label={
            <Space>
              <span>选择柜子</span>
              <span style={{ color: '#DC2626' }}>*</span>
            </Space>
          }
        >
          <DeviceSelector value={selectedDevices} onChange={setSelectedDevices} multiple={true} />
        </Form.Item>

        {/* 商户绑定配置 */}
        <MerchantConfigForm
          merchants={batchMerchants}
          onChange={setBatchMerchants}
        />
      </Form>
    </Modal>
  )
}

export default BatchProfitConfigModal