import { useRef, useState, useEffect } from 'react'
import {
  getMerchantUserList,
  getDeviceProfitConfigList,
  getDeviceProfitConfigDetail,
  editDeviceMerchantProfit,
  PlatformUserTypes
} from '@/apis/admin/platform-user'
import ExcelTable from '@/components/exportExcel'
import BatchProfitConfigModal from './components/BatchProfitConfigModal'
import MerchantConfigForm from './components/MerchantConfigForm'
import { ActionType, ProFormInstance, ProColumns } from '@ant-design/pro-components'
import {
  Button,
  message,
  Tag,
  Tooltip,
  Modal,
  Form,
  Alert
} from 'antd'
import {
  PlusOutlined,
  EditOutlined,
  GroupOutlined,
  InfoCircleOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'

const ProfitShareSetting: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const formRef = useRef<ProFormInstance>()
  const [editModalVisible, setEditModalVisible] = useState(false)
  const [batchModalVisible, setBatchModalVisible] = useState(false)
  const [currentDevice, setCurrentDevice] =
    useState<PlatformUserTypes.DeviceMerchantProfitListDto | null>(null)
  const [editMerchants, setEditMerchants] = useState<PlatformUserTypes.MerchantProfitInfoDto[]>([])

  // 打开编辑弹窗
  const handleOpenEdit = async (record: PlatformUserTypes.DeviceMerchantProfitListDto) => {
    setCurrentDevice(record)
    try {
      const res = await getDeviceProfitConfigDetail(record.id)
      if (res.code === ResultEnum.SUCCESS && res.data) {
        // 使用接口返回的商户分润配置，如果没有则初始化一个空配置
        const profitInfo =
          res.data.merchantProfitInfo && res.data.merchantProfitInfo.length > 0
            ? res.data.merchantProfitInfo
            : [{ merchantId: 0, merchantName: '', divideRatio: 0 }]
        setEditMerchants(profitInfo)
      } else {
        // 如果获取失败，初始化一个空配置
        setEditMerchants([{ merchantId: 0, merchantName: '', divideRatio: 0 }])
      }
    } catch (e) {
      console.error('获取分润详情失败:', e)
      setEditMerchants([{ merchantId: 0, merchantName: '', divideRatio: 0 }])
    }
    setEditModalVisible(true)
  }

  // 保存单柜配置
  const handleSaveEdit = async () => {
    if (!currentDevice) {
      return
    }

    // 过滤掉未选择商户的配置
    const validMerchants = editMerchants.filter(m => m.merchantId > 0)
    if (validMerchants.length === 0) {
      message.error('请至少选择一个商户')
      return
    }

    // 计算公司分成
    const total = validMerchants.reduce((sum, m) => sum + (m.divideRatio || 0), 0)
    const companyRate = 100 - total
    if (companyRate < 0) {
      message.error('商户分成合计不能超过 100%')
      return
    }

    try {
      // 取第一个商户进行配置（每个设备每次配置一个商户）
      const merchant = validMerchants[0]
      const res = await editDeviceMerchantProfit(currentDevice.id, {
        deviceId: currentDevice.id,
        merchantId: merchant.merchantId,
        merchantName: merchant.merchantName,
        divideRatio: merchant.divideRatio
      })

      if (res.code === ResultEnum.SUCCESS) {
        message.success('配置已保存')
        setEditModalVisible(false)
        actionRef.current?.reload()
      } else {
        message.error(res.message || '保存失败')
      }
    } catch (e) {
      console.error('保存配置失败:', e)
      message.error('保存失败')
    }
  }

  // 打开批量配置弹窗
  const handleOpenBatch = () => {
    setBatchModalVisible(true)
  }

  // 批量配置成功回调
  const handleBatchSuccess = () => {
    setBatchModalVisible(false)
    actionRef.current?.reload()
  }

  // 表格列定义
  const columns: ProColumns<PlatformUserTypes.DeviceMerchantProfitListDto>[] = [
    {
      title: '设备编号',
      dataIndex: 'imei',
      key: 'imei',
      width: 160,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>{text}</span>
      )
    },
    {
      title: '设备名称',
      dataIndex: 'deviceName',
      key: 'deviceName',
      width: 150,
      hideInSearch: true
    },
    {
      title: '所属地区',
      key: 'area',
      width: 200,
      hideInSearch: true,
      render: (_, record) => (
        <span>
          {record.provinceName}
          {record.cityName}
          {record.areaName}
        </span>
      )
    },
    {
      title: '绑定商户',
      key: 'merchants',
      width: 180,
      hideInSearch: true,
      render: (_, record) =>
        record.merchantName ? (
          <Tag color="blue">{record.merchantName}</Tag>
        ) : (
          <Tag color="default">未配置</Tag>
        )
    },
    {
      title: '商户分成',
      key: 'merchantTotal',
      width: 120,
      hideInSearch: true,
      render: (_, record) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>{record.divideRatio || 0}%</span>
      )
    },
    {
      title: '公司分成',
      key: 'companyRate',
      width: 120,
      hideInSearch: true,
      render: (_, record) => {
        const companyRate = 100 - (record.divideRatio || 0)
        return (
          <span style={{ fontFamily: 'Courier New, monospace', color: '#2563EB', fontWeight: 600 }}>
            {companyRate}%
          </span>
        )
      }
    },
    {
      title: '操作',
      key: 'option',
      valueType: 'option',
      fixed: 'right',
      width: 80,
      render: (_, record) => [
        <Tooltip title="编辑" key={`${record.id}-edit`}>
          <Button
            type="link"
            title="编辑"
            icon={<EditOutlined />}
            onClick={() => handleOpenEdit(record)}
          />
        </Tooltip>
      ]
    }
  ]

  return (
    <div>
      {/* 顶部提示 */}
      <Alert
        message="分润按柜子维度配置，一个柜子可绑定多个商户，每个商户设定分成比例。公司分成 = 100% - 商户分成合计。分润比例可为0（适用于测试账户、公司内部人员）。修改仅对后续新订单生效。"
        type="info"
        showIcon
        icon={<InfoCircleOutlined />}
        style={{ marginBottom: 20 }}
      />
      <ExcelTable
        key="profit-device-list"
        formRef={formRef}
        columns={columns}
        requestFn={async params => {
          const { page, pageSize, ...rest } = params
          const res = await getDeviceProfitConfigList({
            page,
            pageSize,
            ...rest
          })
          return res as any
        }}
        actionRef={actionRef}
        rowSelection={false}
        options={{
          fullScreen: false,
          reload: true,
          setting: false,
          density: false
        }}
        search={{
          span: 6,
          labelWidth: 'auto'
        }}
        toolBarRenderFn={() => [
          <Button key="batch" type="primary" icon={<GroupOutlined />} onClick={handleOpenBatch}>
            批量配置
          </Button>
        ]}
        scroll={{ x: 1000 }}
      />

      {/* 编辑单柜分润弹窗 */}
      <Modal
        title="编辑柜子分润配置"
        open={editModalVisible}
        onCancel={() => setEditModalVisible(false)}
        onOk={handleSaveEdit}
        width={560}
      >
        {currentDevice && (
          <div style={{ marginBottom: 16, padding: 12, background: '#F8FAFC', borderRadius: 6 }}>
            <div style={{ fontSize: 13, color: '#1E293B', fontWeight: 500 }}>
              设备编号：
              <span style={{ fontFamily: 'Courier New, monospace' }}>{currentDevice.imei}</span>
            </div>
            <div style={{ fontSize: 12, color: '#64748B', marginTop: 4 }}>
              {currentDevice.provinceId}
              {currentDevice.cityId}
              {currentDevice.areaId}
            </div>
          </div>
        )}
        <Form layout="vertical">
          <Form.Item label="绑定商户" style={{ marginBottom: 0 }}>
            <span style={{ fontSize: 12, color: '#64748B', float: 'right' }}>比例可为0</span>
          </Form.Item>
          <MerchantConfigForm
            merchants={editMerchants}
            onChange={setEditMerchants}
            showTitle={false}
          />
        </Form>
      </Modal>

      {/* 批量配置弹窗 */}
      <BatchProfitConfigModal
        open={batchModalVisible}
        onCancel={() => setBatchModalVisible(false)}
        onSuccess={handleBatchSuccess}
      />
    </div>
  )
}

export default ProfitShareSetting